#include <vector>
using namespace std;

class Solution {
public:
    int findCenter(vector<vector<int>>& edges) {
        int u1 = edges[0][0], v1 = edges[0][1];
        int u2 = edges[1][0], v2 = edges[1][1];
        return (u1 == u2 || u1 == v2) ? u1 : v1;
    }
};

class Solution {
    public int findCenter(int[][] edges) {
        int u1 = edges[0][0], v1 = edges[0][1];
        int u2 = edges[1][0], v2 = edges[1][1];
        return (u1 == u2 || u1 == v2) ? u1 : v1;
    }
}

/**
 * @param {number[][]} edges
 * @return {number}
 */
var findCenter = function(edges) {
    const [u1, v1] = edges[0];
    const [u2, v2] = edges[1];
    return (u1 === u2 || u1 === v2) ? u1 : v1;
};
